/**
 * Oyen: an orange cat above the prompt that reacts to commits, tests and builds.
 *
 * Turning it off:
 * - Hide the cat: `/config` → oyen → "Show Oyen" off, or in ~/.claude/settings.json
 *   `"pluginConfigs": { "oyen": { "options": { "enabled": false } } }`. The hooks
 *   still count commits and xp; only the band is gone.
 * - Quiet it: the same place, "Sound" off (`"sound": false`, the default) or
 *   "Stroll" off (`"walk": false`) to keep it still.
 * - Turn the mod off entirely: `/plugin uninstall oyen@oyen` when installed from
 *   the marketplace; when loaded from a folder, drop it from `--plugin-dir` /
 *   `CLAUDE_CODE_PLUGIN_DIRS`; then `/reload-plugins`.
 * - Forget its stats: they live in the mod's `$.store` under the key `stats`.
 */
import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, Timer } from 'claude-code'

import type { Pose, Stats } from '../types'
import type { Language } from './cat'
import {
  asLanguage,
  asStats,
  countTicks,
  dayOf,
  FRESH,
  grow,
  kindOf,
  lineFor,
  moodBar,
  outputFailed,
  POSES,
  visit,
} from './cat'
import { rasterOf, ROWS, WIDTH } from './pixels'
import { restLength, spotOf, STEP_MS, strollLength, trackOf } from './walk'

const pose = atom({ plugin: 'oyen', key: 'pose' } as const, 'idle')
const line = atom({ plugin: 'oyen', key: 'line' } as const, '')
const stats = atom({ plugin: 'oyen', key: 'stats' } as const, FRESH)
const lastActiveAt = atom({ plugin: 'oyen', key: 'lastActiveAt' } as const, 0)
const walk = atom({ plugin: 'oyen', key: 'walk' } as const, { step: 0, isWalking: false })

const STORE_KEY = 'stats'
const MEOW = 'sounds/meow.wav'
const REACTION_MS = 8_000
const IDLE_CHECK_MS = 30_000
const ORANGE = '#ff8c1a'

type Config = { language: Language; isSoundOn: boolean; isWalkOn: boolean }
type Reaction = { pose: Pose; xp?: number; mood?: number; commits?: number }

/** The pending return to the idle pose after a reaction. */
let settle: Timer | undefined

/** How often a stroll starts as a game of chasing the ball. */
const PLAY_CHANCE = 0.25

/** How long `/oyen play` runs after the ball, in steps. */
const PLAY_STEPS = 26

/** Steps left in the current stroll, and ticks left in the rest before the next one. */
let stepsLeft = 0
let restLeft = 3

function meow($: EngineInterface, config: Config) {
  if (config.isSoundOn) {
    void $.audio.play({ asset: MEOW }).catch(() => undefined)
  }
}

async function strike($: EngineInterface, config: Config, next: Pose) {
  await update($, pose, () => next)
  await update($, line, () => lineFor(next, config.language, Math.random()))
}

async function react($: EngineInterface, config: Config, reaction: Reaction) {
  const before = await read($, stats)
  const grown = grow(before, reaction.xp ?? 0, reaction.mood ?? 0)
  const after: Stats = { ...grown.stats, commitsFed: grown.stats.commitsFed + (reaction.commits ?? 0) }

  await update($, stats, () => after)
  await $.store.set(STORE_KEY, after)
  await strike($, config, reaction.pose)

  if (grown.hasLevelledUp) {
    $.ui.toast(`Oyen reached level ${after.level}!`)
    meow($, config)
  }

  settle?.cancel()
  settle = $.clock.after(REACTION_MS, () => {
    void read($, pose).then(now => (now === 'sleep' ? undefined : strike($, config, 'idle')))
  })

  return after
}

async function touch($: EngineInterface, config: Config) {
  const now = await $.clock.now()
  await update($, lastActiveAt, () => now)

  if ((await read($, pose)) === 'sleep') {
    await strike($, config, 'idle')
  }
}

async function watchTodo<T>($: EngineInterface, config: Config, path: string, run: () => Promise<T>) {
  if (!/(^|\/)todo\.md$/.test(path)) {
    return run()
  }

  const before = countTicks(await $.fs.read(path).catch(() => ''))
  const ran = await run()
  const ticked = countTicks(await $.fs.read(path).catch(() => '')) - before

  if (ticked > 0) {
    await react($, config, { pose: 'cheer', xp: 5 * ticked, mood: 3 })
  }

  return ran
}

async function doze($: EngineInterface, config: Config, idleMs: number) {
  const quietFor = (await $.clock.now()) - (await read($, lastActiveAt))

  if (quietFor >= idleMs && (await read($, pose)) !== 'sleep') {
    settle?.cancel()
    await strike($, config, 'sleep')
  }
}

/**
 * One tick of Oyen's strolling: a step, the end of a stroll, or a tick of rest.
 * Only an idle or playing Oyen moves; now and then a stroll starts as a game
 * of chasing the ball, which ends with the stroll.
 */
async function stroll($: EngineInterface, config: Config) {
  const now = await read($, walk)
  const current = await read($, pose)

  if (current !== 'idle' && current !== 'play') {
    if (now.isWalking) {
      stepsLeft = 0
      await update($, walk, held => ({ ...held, isWalking: false }))
    }

    return
  }

  if (stepsLeft > 0) {
    stepsLeft -= 1
    await update($, walk, held => ({ step: held.step + 1, isWalking: true }))
  } else if (now.isWalking) {
    restLeft = restLength(Math.random())
    await update($, walk, held => ({ ...held, isWalking: false }))

    if (current === 'play') {
      await strike($, config, 'idle')
    }
  } else if (restLeft > 0) {
    restLeft -= 1
  } else {
    stepsLeft = strollLength(Math.random())

    if (Math.random() < PLAY_CHANCE) {
      await strike($, config, 'play')
    }
  }
}

export const register: Register = (on, options) => {
  const config: Config = {
    language: asLanguage(options.language),
    isSoundOn: options.sound === true,
    isWalkOn: options.walk !== false,
  }
  const idleMs = Number(options.idleMinutes ?? 10) * 60_000
  const minColumns = Number(options.minColumns ?? 60)

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'oyen',
      description: 'Feed, pet or play with Oyen, or see how it is doing',
      argumentHint: '[feed|pet|play]',
    })

    const now = await $.clock.now()
    const loaded = visit(asStats(await $.store.get(STORE_KEY)), dayOf(now))
    await $.store.set(STORE_KEY, loaded)
    await update($, stats, () => loaded)
    await update($, lastActiveAt, () => now)

    $.clock.every(IDLE_CHECK_MS, () => void doze($, config, idleMs))

    if (config.isWalkOn) {
      $.clock.every(STEP_MS, () => void stroll($, config))
    }

    return next(e)
  })

  on('prompt.submit', async ($, e, next) => {
    await touch($, config)

    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const now = await $.clock.now()
    await update($, lastActiveAt, () => now)

    return next(e)
  })

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const ran = await next(e)
    const kind = kindOf(e.command)
    const hasErrored = ran.deny !== undefined || ran.isError === true
    const hasFailed = hasErrored || (kind !== 'commit' && outputFailed(ran.text ?? ''))

    if (kind === 'commit') {
      await react($, config, hasFailed ? { pose: 'grumpy', mood: -5 } : { pose: 'happy', xp: 10, mood: 5, commits: 1 })
    } else if (kind === 'test') {
      await react($, config, hasFailed ? { pose: 'grumpy', mood: -2 } : { pose: 'cheer', xp: 5, mood: 3 })
    } else if (kind === 'build' && hasFailed) {
      await react($, config, { pose: 'hide', mood: -3 })
    }

    return ran
  })

  on('tool.call', { tool: 'Edit' }, ($, e, next) => watchTodo($, config, e.file_path, () => next(e)))

  on('tool.call', { tool: 'Write' }, ($, e, next) => watchTodo($, config, e.file_path, () => next(e)))

  on('command.run', { command: 'oyen' }, async ($, e) => {
    await touch($, config)
    const wish = e.args.trim().toLowerCase()

    if (wish === 'feed' || wish === 'pet') {
      const reaction: Reaction = wish === 'feed' ? { pose: 'eat', xp: 3, mood: 15 } : { pose: 'purr', xp: 2, mood: 8 }
      const after = await react($, config, reaction)

      if (wish === 'pet') {
        meow($, config)
      }

      return { text: `Oyen: ${await read($, line)}  ${moodBar(after.mood)}` }
    }

    if (wish === 'play') {
      const after = await react($, config, { pose: 'play', xp: 1, mood: 5 })
      stepsLeft = Math.max(stepsLeft, PLAY_STEPS)
      restLeft = 0

      return { text: `Oyen: ${await read($, line)}  ${moodBar(after.mood)}` }
    }

    if (wish !== '') {
      return { text: 'Usage: /oyen [feed|pet|play]' }
    }

    const now = await read($, stats)

    return {
      text: [
        `Oyen, level ${now.level} (${now.xp}/${now.level * 50} xp)`,
        `mood ${moodBar(now.mood)} ${now.mood}/100`,
        `${now.commitsFed} commits fed, ${now.streak}-day streak`,
      ].join('\n'),
    }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const isHidden =
      options.enabled === false ||
      e.props.hasSurvey ||
      e.props.bodyColumns < minColumns ||
      e.props.maxRows < ROWS

    if (isHidden) {
      return next(e)
    }

    const now = await read($, pose)
    const said = await read($, line)
    const grown = await read($, stats)
    const strolled = await read($, walk)
    const track = config.isWalkOn ? trackOf(e.props.bodyColumns) : WIDTH
    const { x, isFacingRight } = spotOf(strolled.step, track - WIDTH)
    const look = { isFacingRight, isStepping: strolled.isWalking && strolled.step % 2 === 1 }
    const { Box, Text } = $.ui.resolve(e)

    let cat
    if (e.surface === 'terminal') {
      const { Raster } = $.ui.resolve(e)
      cat = <Raster key={`oyen-${now}`} columns={WIDTH} rows={ROWS} cells={rasterOf(now, look)} />
    } else {
      const [ears, face, paws] = POSES[now]
      cat = (
        <Box flexDirection="column">
          <Text color={ORANGE}>{ears}</Text>
          <Text color={ORANGE}>{face}</Text>
          <Text color={ORANGE}>{paws}</Text>
        </Box>
      )
    }

    return (
      <Box flexDirection="row">
        <Box width={track} flexShrink={0} marginRight={2}>
          <Box key="oyen-spot" marginLeft={x}>
            {cat}
          </Box>
        </Box>
        <Box flexDirection="column" paddingTop={1}>
          <Text>{said === '' ? '...' : said}</Text>
          <Text dimColor>
            Oyen · Lv {grown.level} · {moodBar(grown.mood)} · {grown.streak}d streak · {grown.commitsFed} commits
          </Text>
        </Box>
      </Box>
    )
  })
}

