import type { Pose, Stats } from '../types'
import type { Language } from './lines'
import { LANGUAGES, LINES } from './lines'

export type { Language } from './lines'

export const POSES: Record<Pose, readonly [string, string, string]> = {
  idle: [' /\\_/\\ ', '( o.o )', ' > ^ < '],
  happy: [' /\\_/\\ ', '( ^.^ )', ' > ♥ < '],
  grumpy: [' /\\_/\\ ', '( >.< )', ' > ~ < '],
  sleep: [' /\\_/\\  z', '( -.- ) Z', ' > ^ < '],
  cheer: ['\\/\\_/\\/', '( ^o^ )', ' /   \\ '],
  hide: ['  ___  ', ' |. .| ', ' |___| '],
  eat: [' /\\_/\\ ', '( ^~^ )', ' > ><> '],
  purr: [' /\\_/\\ ', '( =w= )', ' > ^ < '],
  play: [' /\\_/\\   o', '( ^o^ )  ', ' />  >  '],
}

export function asLanguage(value: unknown): Language {
  return LANGUAGES.find(language => language === value) ?? 'en'
}

export function lineFor(pose: Pose, language: Language, roll: number): string {
  const lines = LINES[language][pose]

  return lines[Math.floor(roll * lines.length) % lines.length] ?? '...'
}

export const FRESH: Stats = {
  mood: 70,
  xp: 0,
  level: 1,
  commitsFed: 0,
  streak: 0,
  lastDay: '',
}

export function asStats(value: unknown): Stats {
  if (typeof value !== 'object' || value === null) {
    return FRESH
  }

  return { ...FRESH, ...(value as Partial<Stats>) }
}

export function xpToLevel(level: number): number {
  return level * 50
}

/** Adds xp and mood, levelling up as often as the xp allows. */
export function grow(stats: Stats, xp: number, mood: number): { stats: Stats; hasLevelledUp: boolean } {
  let next = {
    ...stats,
    xp: stats.xp + xp,
    mood: Math.max(0, Math.min(100, stats.mood + mood)),
  }
  let hasLevelledUp = false

  while (next.xp >= xpToLevel(next.level)) {
    next = { ...next, xp: next.xp - xpToLevel(next.level), level: next.level + 1 }
    hasLevelledUp = true
  }

  return { stats: next, hasLevelledUp }
}

export function dayOf(ms: number): string {
  const date = new Date(ms)
  const month = String(date.getMonth() + 1).padStart(2, '0')
  const day = String(date.getDate()).padStart(2, '0')

  return `${date.getFullYear()}-${month}-${day}`
}

function daysBetween(from: string, to: string): number {
  return Math.round((Date.parse(to) - Date.parse(from)) / 86_400_000)
}

/** Counts today in the streak; a gap resets it and costs some mood. */
export function visit(stats: Stats, today: string): Stats {
  if (stats.lastDay === today) {
    return stats
  }

  const gap = stats.lastDay === '' ? 1 : daysBetween(stats.lastDay, today)
  const streak = gap === 1 ? stats.streak + 1 : 1
  const mood = Math.max(20, stats.mood - 5 * Math.max(0, gap - 1))

  return { ...stats, streak, mood, lastDay: today }
}

export function moodBar(mood: number): string {
  const hearts = Math.round(mood / 20)

  return '♥'.repeat(hearts) + '♡'.repeat(5 - hearts)
}

const COMMIT = /(^|[\s;&|(])git\s+(?:-\S+\s+(?:\S+\s+)?)*commit\b/
const TEST = /\b(test|tests|pytest|vitest|jest|phpunit|pest)\b/
const BUILD = /\b(build|tsc)\b/

export type CommandKind = 'commit' | 'test' | 'build' | 'other'

export function kindOf(command: string): CommandKind {
  if (COMMIT.test(command)) {
    return 'commit'
  }

  if (TEST.test(command)) {
    return 'test'
  }

  return BUILD.test(command) ? 'build' : 'other'
}

const FAILURE_OUTPUT = [
  /\b[1-9]\d* (?:fail|failed|failing|failures?|errors?)\b/i, // "1 fail", "2 failed", never "0 fail"
  /^\s*(?:FAIL|FAILED|FAILURES!)(?:\s|$)/m, // jest, pytest, phpunit
  /\(fail\)/, // bun
  /\berror TS\d+/, // tsc
  /^\s*(?:npm (?:ERR!|error)|error[:\s])/im,
]

/** Whether a command's output reports a failure, for runs whose exit code a pipe hid. */
export function outputFailed(text: string): boolean {
  return FAILURE_OUTPUT.some(pattern => pattern.test(text))
}

export function countTicks(text: string): number {
  return (text.match(/^\s*[-*]\s+\[[xX]\]/gm) ?? []).length
}

