import type { Pose } from '../types'

/**
 * Oyen as pixel art: 28 x 10 pixels, drawn two pixels per terminal cell
 * (a half block whose foreground paints the top pixel and background the
 * bottom one), so 28 columns by 5 rows. Columns 0-5 hold a prop (Z's, a
 * heart, a fish); columns 6-27 hold the cat: its head facing out, its body
 * lying behind it and its tail curling up at the far end.
 */
export const WIDTH = 28
export const HEIGHT = 10
export const ROWS = HEIGHT / 2

const DEFAULT = 0x01000000

/** One letter per colour; `.` is see-through (the terminal's own background). */
const PALETTE: Record<string, number> = {
  o: 0xf28c28, // fur: one flat orange
  k: 0x000000, // eyes and mouth
  p: 0xf4a0b0, // heart
  g: 0x4fb3a9, // ball
  b: 0x8b5a2b, // box
  B: 0x6b4320, // box rim
  f: 0x6fa8dc, // fish
  z: 0xbcd4ff, // sleep Z
  y: 0xffd84a, // sparkles
  r: 0xe0453a, // anger mark
}

type Cat = readonly string[]

/**
 * One row of the cat: a margin pixel, the head (9), the body (9) and the
 * tail (3), so 22 pixels.
 */
function row(head: string, body = '.........', tail = '...'): string {
  return `.${head}${body}${tail}`
}

const BACK = 'ooooooooo'

const SITTING: Cat = [
  row('.o.....o.'),
  row('ooo...ooo'),
  row('ooooooooo', '.........', '.o.'),
  row('ooooooooo', '.........', '.o.'),
  row('ookoookoo', BACK, '.o.'),
  row('ooookoooo', BACK, '.o.'),
  row('.oooooooo', BACK, 'oo.'),
  row('.oooooooo', BACK, 'o..'),
  row('.oooooooo', BACK, 'o..'),
  row('.oo..oo..', '....oo.oo'),
]

/** The sitting cat with some rows' heads swapped: `{ 4: 'okokokoko' }`. */
function face(heads: Readonly<Record<number, string>>): Cat {
  return SITTING.map((line, at) => {
    const head = heads[at]

    return head === undefined ? line : `.${head}${line.slice(10)}`
  })
}

const HAPPY_EYES = { 3: 'ookoookoo', 4: 'okokokoko' }
const CLOSED_EYES = { 4: 'okkoookko' }
const OPEN_MOUTH = { 6: '.oookoooo' }

const CATS: Record<Pose, Cat> = {
  idle: SITTING,
  happy: face(HAPPY_EYES),
  grumpy: face({ 0: '.........', 1: 'oo.....oo', 3: 'okoooooko' }),
  sleep: face(CLOSED_EYES),
  cheer: face({ ...HAPPY_EYES, ...OPEN_MOUTH }),
  hide: [
    '......................',
    '......................',
    row('.o.....o.'),
    row('ooo...ooo', '...o.....'),
    row('ooooooooo', '...o.....'),
    row('ookoookoo', '...o.....'),
    'BBBBBBBBBBBBBB........',
    'bbbbbbbbbbbbbb........',
    'bbbbbbbbbbbbbb........',
    'bbbbbbbbbbbbbb........',
  ],
  eat: face({ ...HAPPY_EYES, ...OPEN_MOUTH }),
  purr: face(CLOSED_EYES),
  play: face({ ...HAPPY_EYES, ...OPEN_MOUTH }),
}

/** Paws mid-stride: front and back paws each a pixel further along. */
const STRIDE = row('..oo..oo.', '...oo.oo.')

/** Poses that move along the strip, and so take a stride on every other step. */
const MOVING: readonly Pose[] = ['idle', 'play']

/** The ball Oyen chases, on the ground and in the air, alternating each step. */
const BALL_DOWN = ['......', '......', '......', '......', '......', '......', '..gg..', '.gggg.', '.gggg.', '..gg..']
const BALL_UP = ['......', '......', '..gg..', '.gggg.', '.gggg.', '..gg..', '......', '......', '......', '......']

const NOTHING = ['......', '......', '......', '......', '......', '......', '......', '......', '......', '......']

const PROPS: Partial<Record<Pose, readonly string[]>> = {
  sleep: ['zzzzz.', '...z..', '..z...', '.z....', 'zzzzz.', '......', '......', '......', '......', '......'],
  purr: ['......', '.p.p..', 'ppppp.', '.ppp..', '..p...', '......', '......', '......', '......', '......'],
  cheer: ['......', '.y....', 'yyy...', '.y..y.', '...yyy', '....y.', '......', '......', '......', '......'],
  grumpy: ['......', '.r.r..', '..r...', '.r.r..', '......', '......', '......', '......', '......', '......'],
  eat: ['......', '......', '......', '......', '......', '......', 'f..ff.', 'ffffkf', 'f..ff.', '......'],
}

/** Which way Oyen faces and whether it is mid-stride. */
export type Look = { isFacingRight: boolean; isStepping: boolean }

const STILL: Look = { isFacingRight: false, isStepping: false }

function mirror(line: string): string {
  return [...line].reverse().join('')
}

/**
 * A pose's pixel rows. Facing left (as drawn), the prop is on the left and
 * the cat's head leads; facing right, the cat is flipped and the prop moves
 * to its other side, unflipped so a Z stays a Z.
 */
export function pixelRows(pose: Pose, look: Look = STILL): readonly string[] {
  const prop = pose === 'play' ? (look.isStepping ? BALL_UP : BALL_DOWN) : (PROPS[pose] ?? NOTHING)
  const isStriding = look.isStepping && MOVING.includes(pose)
  const cat = isStriding ? [...CATS[pose].slice(0, 9), STRIDE] : CATS[pose]

  return cat.map((line, at) => {
    const beside = prop[at] ?? '......'

    return look.isFacingRight ? `${mirror(line)}${beside}` : `${beside}${line}`
  })
}

function colourOf(letter: string | undefined): number | undefined {
  return letter === undefined || letter === '.' ? undefined : PALETTE[letter]
}

/** The cells of one pose: [codePoint, foreground, background] per cell, row-major. */
export function cellsOf(pose: Pose, look: Look = STILL): number[] {
  const rows = pixelRows(pose, look)
  const cells: number[] = []

  for (let row = 0; row < ROWS; row += 1) {
    for (let column = 0; column < WIDTH; column += 1) {
      const top = colourOf(rows[row * 2]?.[column])
      const bottom = colourOf(rows[row * 2 + 1]?.[column])

      if (top === undefined && bottom === undefined) {
        cells.push(0x20, DEFAULT, DEFAULT)
      } else if (top === undefined) {
        cells.push(0x2584, bottom ?? DEFAULT, DEFAULT) // ▄
      } else {
        cells.push(0x2580, top, bottom ?? DEFAULT) // ▀
      }
    }
  }

  return cells
}

const BASE64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

/** Packs u32 words little-endian and encodes them as padded base64, as Raster's `cells` takes them. */
export function packCells(words: readonly number[]): string {
  const bytes = words.flatMap(word => [word & 0xff, (word >>> 8) & 0xff, (word >>> 16) & 0xff, (word >>> 24) & 0xff])
  let text = ''

  for (let at = 0; at < bytes.length; at += 3) {
    const [a = 0, b = 0, c = 0] = bytes.slice(at, at + 3)
    const left = bytes.length - at
    text += BASE64[a >> 2]
    text += BASE64[((a & 3) << 4) | (b >> 4)]
    text += left > 1 ? BASE64[((b & 15) << 2) | (c >> 6)] : '='
    text += left > 2 ? BASE64[c & 63] : '='
  }

  return text
}

export function rasterOf(pose: Pose, look: Look = STILL): string {
  return packCells(cellsOf(pose, look))
}

