import { WIDTH } from './pixels'

/** How often Oyen takes a step while strolling. */
export const STEP_MS = 300

/** Room left beside the strip for the speech line and the stats row. */
const TEXT_ROOM = 50

/** The furthest Oyen strolls from its starting spot, in columns. */
const MAX_SPAN = 30

/** The strip Oyen strolls along: as wide as the band spares, never narrower than the cat. */
export function trackOf(bodyColumns: number): number {
  return Math.max(WIDTH, Math.min(WIDTH + MAX_SPAN, bodyColumns - TEXT_ROOM))
}

/**
 * Where `step` puts Oyen on a strip with `span` columns to spare: out to the
 * right, then back, then out again, facing the way it goes.
 */
export function spotOf(step: number, span: number): { x: number; isFacingRight: boolean } {
  if (span <= 0) {
    return { x: 0, isFacingRight: false }
  }

  const at = step % (2 * span)

  return at < span ? { x: at, isFacingRight: true } : { x: 2 * span - at, isFacingRight: false }
}

/** A stroll of 8 to 32 steps. */
export function strollLength(roll: number): number {
  return 8 + Math.floor(roll * 25)
}

/** A rest of 10 to 40 ticks (3 to 12 seconds) between strolls. */
export function restLength(roll: number): number {
  return 10 + Math.floor(roll * 31)
}

